using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Xml.Linq;using V15Voice;
public static class Render411Tests {
 static int n;static void Check(bool b,string name){if(!b)throw new Exception(name);n++;Console.WriteLine("PASS "+name);}
 sealed class GuardRewrite:ITextRewriter {public string Root,Text;public int Calls;public string Rewrite(string p,Func<bool> c,Action<string> a){if(RenderPipelineFixture.Alive(Root))throw new Exception("Worker still resident during language-model call");Calls++;return LocalAi.Json(new AiRewriteText{cues=new List<AiCueText>{new AiCueText{id=1,text=Text}}});}}
 public static int Main(){try{
  string root=RenderPipelineFixture.Root(),source=RenderPipelineFixture.Source(root);RenderOptions o;var first=RenderPipelineFixture.Run(root,source,1,out o);Check(first.Rendered&&first.Status=="FINAL_VERIFIED","Cold locked SRT still publishes verified PCM with one report");Check(first.Bundle.Reports.Length==1,"Performance instrumentation creates no extra report in mode 1");Check(RenderPipelineFixture.Lines(root,"requests")==8&&RenderPipelineFixture.Lines(root,"ffmpeg-calls")>=8,"Cold path measures eight real fixture TTS requests and actual FFmpeg fitting");int requests=RenderPipelineFixture.Lines(root,"requests"),tempo=RenderPipelineFixture.Lines(root,"ffmpeg-calls");string hash=StateFiles.Hash(first.Bundle.Wave);File.WriteAllText(Path.Combine(root,"expected-wave-sha"),hash);File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"validation/render411-checkpoint-root.txt"),root);var again=RenderPipelineFixture.Run(root,source,1,out o);Check(again.Rendered&&RenderPipelineFixture.Lines(root,"requests")==requests&&RenderPipelineFixture.Lines(root,"ffmpeg-calls")==tempo,"Warm locked output reuses fitted PCM without repeating TTS or atempo");Check(StateFiles.Hash(again.Bundle.Wave)==hash,"Warm and cold locked outputs contain exactly identical WAV bytes");Check(File.ReadAllText(again.Bundle.Primary).Contains("LOCKED_CHECKPOINT: 8")&&File.ReadAllText(again.Bundle.Primary).Contains("THỜI GIAN XỬ LÝ THỰC"),"The existing report exposes measured timings and actual fitted-cue reuse");
  var cue=BatchJob.Load(source).Cues[0];var next=BatchJob.Load(source).Cues[1];using(var e=RenderPipelineFixture.Engine(root,Path.Combine(root,"state"))){var options=RenderPipelineFixture.Options(root,source);Check(LockedCueReuse.Read(cue,next,e,options,0)!=null,"A matching locked-cue checkpoint is usable after hash/geometry/profile checks");cue.Text+=" changed";Check(LockedCueReuse.Read(cue,next,e,options,0)==null,"Changed wording cannot reuse old fitted PCM");cue=BatchJob.Load(source).Cues[0];next.Start+=.02;Check(LockedCueReuse.Read(cue,next,e,options,0)==null,"Changed following timecode invalidates a locked checkpoint");next=BatchJob.Load(source).Cues[1];e.VoiceName="different";Check(LockedCueReuse.Read(cue,next,e,options,0)==null,"Changing the voice invalidates fitted-cue reuse");e.VoiceName="fixture-A";options.MaxSpeed=1.2;Check(LockedCueReuse.Read(cue,next,e,options,0)==null,"Changing fitting limits invalidates fitted-cue reuse");options.MaxSpeed=1.25;e.Archive.Refresh=true;Check(LockedCueReuse.Read(cue,next,e,options,0)==null,"Explicit audio refresh bypasses fitted-cue reuse too");}
  string metadata=Directory.GetFiles(Path.Combine(root,"pcm/locked-cues"),"cue.xml",SearchOption.AllDirectories).First();var xml=XElement.Load(metadata);string audio=StateFiles.S(xml,"audio");var bytes=File.ReadAllBytes(audio);bytes[50]^=3;File.WriteAllBytes(audio,bytes);var m=AiRepairSession.ReadMeasurement(xml);Check(!m.Valid,"Corrupted fitted audio fails full PCM hash validation");var recovered=RenderPipelineFixture.Run(root,source,1,out o);Check(recovered.Rendered&&StateFiles.Hash(recovered.Bundle.Wave)==hash&&RenderPipelineFixture.Lines(root,"ffmpeg-calls")>tempo,"A corrupted checkpoint is rebuilt from valid source audio, preserving the original WAV bytes");Check(File.ReadAllText(recovered.Bundle.Primary).Contains("LOCKED_CHECKPOINT: 7"),"Rebuilding one corrupt cue keeps the other seven fitted checkpoints");
  root=RenderPipelineFixture.Root();source=RenderPipelineFixture.Source(root);var auto=RenderPipelineFixture.Run(root,source,2,out o);Check(auto.Rendered&&auto.Status=="FINAL_VERIFIED"&&auto.Bundle.Reports.Length==2,"Mode 2 remains unattended with exactly its two reports");Check(RenderPipelineFixture.Lines(root,"starts")==1&&RenderPipelineFixture.Lines(root,"requests")==8,"Eight passing AI measurements use one actual external worker process");Check(o.RunReport.Units.All(u=>u.GeneratedCalls==0&&u.CacheCalls==1&&u.CachedFit),"Final locked WAV uses every matching AI-measured PCM instead of regenerating/refitting it");Check(auto.Cues.Select(c=>c.Text).SequenceEqual(BatchJob.Load(source).Cues.Select(c=>c.Text))&&o.AiRepair.Rows.All(r=>r.FinalVerified),"PCM reuse preserves every source word and confirms each final cue");Check(!RenderPipelineFixture.Alive(root),"The shared measuring worker is disposed before finishing the job");var customReport=new VoiceRenderReport(BatchJob.Load(source).Cues,null,new RenderOptions{Punctuation=PunctuationMode.Custom},Path.Combine(root,"report-probe.wav"));customReport.BeginUnit("Cached custom punctuation.");customReport.CachedLockedCue(new LockedCueAudio{Natural=new Wave{Rate=24000,Samples=new short[24000]},Audio=new Wave{Rate=24000,Samples=new short[24000]},Tts=.8,Pauses=.2},new Cue{Start=0,End=2});Check(!customReport.Current.WorkingBefore.HasValue,"Cached custom-pause audio does not invent an unrecorded post-pause-compression duration");Check(File.ReadAllText(auto.Bundle.Primary).Contains("AI_MEASURED_PCM: 8")&&File.ReadAllText(auto.Bundle.Changes).Contains("ĐÃ SỬA: 0"),"Timings and bilingual changes report distinguish reuse from AI wording changes");
  using(var e=RenderPipelineFixture.Engine(root)){var options=RenderPipelineFixture.Options(root,source);options.ReuseLockedAudio=false;options.AiRepair=o.AiRepair;var cues=BatchJob.Load(source).Cues;Check(LockedCueReuse.Read(cues[0],cues[1],e,options,0)!=null,"Legacy measured sessions can be reused without new on-disk cue checkpoints");var row=o.AiRepair.Rows[0];row.Original.NeedsRepair=true;Check(LockedCueReuse.Read(cues[0],cues[1],e,options,0)==null,"A measurement still needing repair can never become accepted cached output");row.Original.NeedsRepair=false;row.Original.Speed=Double.NaN;Check(LockedCueReuse.Read(cues[0],cues[1],e,options,0)==null,"Non-finite cached timing metadata is rejected");}
  root=RenderPipelineFixture.Root();source=RenderPipelineFixture.Source(root,4,3.2);var words=BatchJob.Load(source).Cues;words[0].Speaker=words[1].Speaker="A";words[2].Speaker=words[3].Speaker="B";File.WriteAllText(source,Scripts.ToSrt(words));var settings=RenderPipelineFixture.Settings();settings.TwoVoices=true;var session=AiRepairSession.Open(source,words,Path.Combine(root,"state"),settings,false,"two-role-fixture");int engines=0;AiTimeline.Run(session,new RenderPipelineFixture.NeverRewrite(),role=>{Check(!RenderPipelineFixture.Alive(root),"The previous role is released before the next role obtains a worker");engines++;return RenderPipelineFixture.Engine(root,null,role);},()=>false,(p,t)=>{},true,false);Check(engines==2&&RenderPipelineFixture.Lines(root,"starts")==2&&session.Ready,"Contiguous A/A/B/B uses two worker lifetimes and keeps all four measurements");Check(!RenderPipelineFixture.Alive(root),"Both roles are released after measurement");
  root=RenderPipelineFixture.Root();source=RenderPipelineFixture.Source(root,2,6);words=BatchJob.Load(source).Cues;session=AiRepairSession.Open(source,words,Path.Combine(root,"state"),RenderPipelineFixture.Settings(),true,"release-before-ai");var writer=new GuardRewrite{Root=root,Text=words[0].Text};AiTimeline.Run(session,writer,role=>RenderPipelineFixture.Engine(root),()=>false,(p,t)=>{},true,true,words[0].Id,false);Check(writer.Calls==2&&session.Rows[0].Attempts.All(a=>a.Code=="NO_NEW_TEXT"),"Repeated AI output stops after distinct strategies and the worker was released before every model call");Check(!RenderPipelineFixture.Alive(root),"No TTS worker leaks after an unsuccessful repair");
  root=RenderPipelineFixture.Root();source=RenderPipelineFixture.Source(root,4,3.2);words=BatchJob.Load(source).Cues;session=AiRepairSession.Open(source,words,Path.Combine(root,"state"),RenderPipelineFixture.Settings(),false,"cancel-fixture");bool cancelled=false,caught=false;try{AiTimeline.Run(session,new RenderPipelineFixture.NeverRewrite(),role=>RenderPipelineFixture.Engine(root),()=>cancelled,(p,t)=>{if(t.StartsWith("Đo chặng 2"))cancelled=true;},true,false);}catch(OperationCanceledException){caught=true;}Check(caught&&!RenderPipelineFixture.Alive(root)&&session.Rows[0].Original.Valid,"Cancellation disposes the warm worker and retains the already verified first cue");
  root=RenderPipelineFixture.Root();source=RenderPipelineFixture.Source(root,1,3.2);var snapshot=BatchJob.Load(source).Cues[0];using(var e=RenderPipelineFixture.Engine(root)){var options=RenderPipelineFixture.Options(root,source);var pcm=new Wave{Rate=24000,Samples=Enumerable.Range(0,48000).Select(i=>(short)(5000*Math.Sin(i*.06))).ToArray()};snapshot.Speed=1;string text=snapshot.Text;var save=LockedCueReuse.PrepareWrite(snapshot,null,e,options,pcm,pcm,2,0,0);e.VoiceName="changed-role";options.BaseSpeed=1.1;snapshot.Text="A changed mutable cue.";save();e.VoiceName="fixture-A";options.BaseSpeed=1;snapshot.Text=text;Check(LockedCueReuse.Read(snapshot,null,e,options,0)!=null,"Deferred PCM I/O snapshots the voice, cue and fitting data before the next cue can mutate them");}bool drained=false;using(var writes=new CueCheckpointWriter(message=>{throw new IOException("unavailable activity sink");})){writes.Add(()=>{throw new IOException("simulated cache disk error");});writes.Add(()=>{drained=true;});}Check(drained,"Cache I/O failures remain nonfatal and disposal drains later successful writes");
  var weight=new BatchJob();weight.Cues=new List<Cue>{new Cue{Text="one two three"}};int prior=weight.EstimatedWorkWords;weight.Cues=new List<Cue>{new Cue{Text="one two three four five"}};Check(prior==3&&weight.EstimatedWorkWords==5,"Cached ETA word weights update when the source snapshot changes");
  Console.WriteLine("TOTAL RENDER411 "+n+" PASS. Real external processes and FFmpeg; synthetic speech, no Windows/GPU speed claim.");return 0;
 }catch(Exception ex){Console.WriteLine(ex);return 1;}}
}
